package oauthserver

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/SAP/astonish/pkg/store"
	"golang.org/x/crypto/bcrypt"
)

// ClientInput is the administrative, non-secret configuration of an OAuth
// client. Client secrets are generated by the server and returned once only.
type ClientInput struct {
	// OwnerUserID is immutable once created. OrgID and TeamID define the
	// tenant context placed into service-principal tokens.
	Name, ClientType, OwnerUserID, OrgID, TeamID string
	RedirectURIs                                 []string
	GrantTypes                                   []string
	Resources                                    []string
	Scopes                                       []string
	Active                                       bool
}

// Discovery describes the stable public endpoints for an Astonish issuer.
type Discovery struct {
	Issuer                string `json:"issuer"`
	Resource              string `json:"resource"`
	AuthorizationEndpoint string `json:"authorization_endpoint"`
	TokenEndpoint         string `json:"token_endpoint"`
	JWKSURI               string `json:"jwks_uri"`
	RevocationEndpoint    string `json:"revocation_endpoint"`
	IntrospectionEndpoint string `json:"introspection_endpoint"`
}

func (s *Server) Discovery() Discovery {
	return Discovery{
		Issuer: s.config.Issuer, Resource: s.config.Resource,
		AuthorizationEndpoint: s.config.Issuer + "/oauth/authorize",
		TokenEndpoint:         s.config.Issuer + "/oauth/token",
		JWKSURI:               s.config.Issuer + "/oauth/jwks",
		RevocationEndpoint:    s.config.Issuer + "/oauth/revoke",
		IntrospectionEndpoint: s.config.Issuer + "/oauth/introspect",
	}
}

func (s *Server) ListClients(ctx context.Context) ([]store.OAuthClient, error) {
	return s.store.ListOAuthClients(ctx)
}

// ListClientsForOwner returns only clients owned by the authenticated user.
func (s *Server) ListClientsForOwner(ctx context.Context, ownerUserID string) ([]store.OAuthClient, error) {
	return s.store.ListOAuthClientsForOwner(ctx, ownerUserID)
}

// CreateClient creates an OAuth client. Confidential clients receive a newly
// generated secret; callers must show it once and must not persist it in logs.
func (s *Server) CreateClient(ctx context.Context, input ClientInput) (store.OAuthClient, string, error) {
	if err := validateClientInput(input); err != nil {
		return store.OAuthClient{}, "", err
	}
	id, err := randomHandle()
	if err != nil {
		return store.OAuthClient{}, "", fmt.Errorf("generate client ID: %w", err)
	}
	scopes, err := normalizeClientScopes(input.Scopes)
	if err != nil {
		return store.OAuthClient{}, "", err
	}
	client := store.OAuthClient{OwnerUserID: input.OwnerUserID, OrgID: input.OrgID, TeamID: input.TeamID, ClientID: "ast_" + id, Name: strings.TrimSpace(input.Name), ClientType: input.ClientType, RedirectURIs: input.RedirectURIs, GrantTypes: input.GrantTypes, Resources: input.Resources, Scopes: scopes, Active: input.Active, CreatedAt: time.Now().UTC(), UpdatedAt: time.Now().UTC()}
	secret, err := setNewSecret(&client)
	if err != nil {
		return store.OAuthClient{}, "", err
	}
	if err := s.store.CreateOAuthClient(ctx, client); err != nil {
		return store.OAuthClient{}, "", fmt.Errorf("create OAuth client: %w", err)
	}
	return client, secret, nil
}

// UpdateClient changes client metadata, preserving its secret unless rotate is
// true. A rotation returns a replacement secret once only.
func (s *Server) UpdateClient(ctx context.Context, clientID string, input ClientInput, rotate bool) (store.OAuthClient, string, error) {
	if err := validateClientInput(input); err != nil {
		return store.OAuthClient{}, "", err
	}
	client, err := s.store.GetOAuthClient(ctx, clientID)
	if err != nil {
		return store.OAuthClient{}, "", fmt.Errorf("get OAuth client: %w", err)
	}
	if client == nil {
		return store.OAuthClient{}, "", fmt.Errorf("OAuth client not found")
	}
	scopes, err := normalizeClientScopes(input.Scopes)
	if err != nil {
		return store.OAuthClient{}, "", err
	}
	client.Name, client.ClientType = strings.TrimSpace(input.Name), input.ClientType
	client.RedirectURIs, client.GrantTypes, client.Resources, client.Scopes, client.Active = input.RedirectURIs, input.GrantTypes, input.Resources, scopes, input.Active
	client.UpdatedAt = time.Now().UTC()
	secret := ""
	if rotate {
		secret, err = setNewSecret(client)
		if err != nil {
			return store.OAuthClient{}, "", err
		}
	}
	if err := s.store.UpdateOAuthClient(ctx, *client); err != nil {
		return store.OAuthClient{}, "", fmt.Errorf("update OAuth client: %w", err)
	}
	return *client, secret, nil
}

func (s *Server) DeleteClient(ctx context.Context, clientID string) error {
	if err := s.store.DeleteOAuthClient(ctx, clientID); err != nil {
		return fmt.Errorf("delete OAuth client: %w", err)
	}
	return nil
}

func validateClientInput(input ClientInput) error {
	if strings.TrimSpace(input.Name) == "" || (input.ClientType != "public" && input.ClientType != "confidential") {
		return fmt.Errorf("name and client type (public or confidential) are required")
	}
	if strings.TrimSpace(input.OwnerUserID) == "" || strings.TrimSpace(input.OrgID) == "" || strings.TrimSpace(input.TeamID) == "" {
		return fmt.Errorf("OAuth client owner, organization, and team are required")
	}
	if len(input.GrantTypes) == 0 || len(input.Resources) == 0 {
		return fmt.Errorf("at least one grant type and resource are required")
	}
	if _, err := normalizeClientScopes(input.Scopes); err != nil {
		return err
	}
	if input.ClientType == "public" && (!contains(input.GrantTypes, GrantAuthorizationCode) || len(input.RedirectURIs) == 0) {
		return fmt.Errorf("public clients must allow authorization_code with at least one redirect URI")
	}
	return nil
}

func setNewSecret(client *store.OAuthClient) (string, error) {
	if client.ClientType == "public" {
		client.SecretHash = ""
		return "", nil
	}
	secret, err := randomHandle()
	if err != nil {
		return "", fmt.Errorf("generate client secret: %w", err)
	}
	hash, err := bcrypt.GenerateFromPassword([]byte(secret), bcrypt.DefaultCost)
	if err != nil {
		return "", fmt.Errorf("hash client secret: %w", err)
	}
	client.SecretHash = string(hash)
	return secret, nil
}
